import type { CSSProperties, ReactNode, Ref } from "react";
import { ChevronLeft, ChevronRight } from "./icons";
import { Button } from "./Button";
import "./Pagination.css";

type PaginationItem = number | "ellipsis";
type PaginationLayout = "pages" | "compact";

export interface PaginationProps {
  /**
   * Which parts render. `pages` shows Previous, the page buttons and Next; `compact` shows only
   * `‹ n / m ›`, for a footer with no room for a page row.
   *
   * @default "pages"
   */
  layout?: PaginationLayout;
  /** Current page, 1-based. */
  page: number;
  /** Total page count. */
  total: number;
  /** Called with the requested page. */
  onPageChange: (page: number) => void;
  /** Number of pages shown on each side of the current page. */
  siblingCount?: number;
  /** Label for the previous-page control (the `pages` layout; `compact` shows a chevron). */
  previousLabel?: ReactNode;
  /** Label for the next-page control (the `pages` layout; `compact` shows a chevron). */
  nextLabel?: ReactNode;
  /** Accessible name of the compact layout's icon-only previous control. Defaults to
      `previousLabel` when that is a string, else "Previous". */
  previousAriaLabel?: string;
  /** Accessible name of the compact layout's icon-only next control. Defaults to `nextLabel` when
      that is a string, else "Next". */
  nextAriaLabel?: string;
  /** Builds each page button's accessible name. */
  pageLabel?: (page: number) => string;
  /** Builds the compact layout's spoken status, read in place of the visible `n / m`. */
  statusLabel?: (page: number, total: number) => string;
  /** Accessible name for the navigation landmark. */
  "aria-label"?: string;
  /** Additional class. sd-pagination is always retained. */
  className?: string;
  /** Inline style — passed through to the nav DOM node. */
  style?: CSSProperties;
  /** Passed to the underlying nav DOM node. */
  ref?: Ref<HTMLElement>;
}

function clampPage(page: number, total: number) {
  return Math.min(Math.max(page, 1), Math.max(total, 1));
}

function getVisiblePages(page: number, total: number, siblingCount: number) {
  const current = clampPage(page, total);
  const siblings = Math.max(siblingCount, 0);
  const pages: PaginationItem[] = [];
  const start = Math.max(current - siblings, 2);
  const end = Math.min(current + siblings, total - 1);

  pages.push(1);

  if (start > 2) {
    pages.push("ellipsis");
  }

  for (let item = start; item <= end; item += 1) {
    pages.push(item);
  }

  if (end < total - 1) {
    pages.push("ellipsis");
  }

  if (total > 1) {
    pages.push(total);
  }

  return pages;
}

export function Pagination({
  layout = "pages",
  page,
  total,
  onPageChange,
  siblingCount = 1,
  previousLabel = "Previous",
  nextLabel = "Next",
  previousAriaLabel,
  nextAriaLabel,
  pageLabel = (item) => `Page ${item}`,
  statusLabel = (current, count) => `Page ${current} of ${count}`,
  "aria-label": ariaLabel = "Pagination",
  className,
  style,
  ref,
}: PaginationProps) {
  const pageCount = Math.max(total, 1);
  const currentPage = clampPage(page, pageCount);
  const visiblePages = getVisiblePages(currentPage, pageCount, siblingCount);

  if (layout === "compact") {
    // `||`, not `??`: an empty string would leave an icon-only button with no name.
    const previousName = previousAriaLabel || (typeof previousLabel === "string" && previousLabel) || "Previous";
    const nextName = nextAriaLabel || (typeof nextLabel === "string" && nextLabel) || "Next";
    return (
      <nav
        ref={ref}
        aria-label={ariaLabel}
        data-layout="compact"
        className={className ? `sd-pagination ${className}` : "sd-pagination"}
        style={style}
      >
        <Button
          variant="ghost"
          size="small"
          isIconOnly
          aria-label={previousName}
          data-layout="compact"
          className="sd-pagination__control"
          isDisabled={currentPage <= 1}
          onPress={() => onPageChange(currentPage - 1)}
        >
          <ChevronLeft aria-hidden size="1em" />
        </Button>
        {/* The visible `n / m` is hidden from assistive tech, which reads the status label instead
            ("Page 3 of 10" rather than "3 slash 10"); polite, so paging announces the new page. */}
        <span role="status" className="sd-pagination__status">
          {/* `dir="ltr"`: under RTL the bidi algorithm would reorder "3 / 10" into "10 / 3", which
              reads as page ten of three. A count reads left to right in every script here. */}
          {/* The count is the line, so it carries the role and its emphasized page is a run in it. */}
          <span aria-hidden="true" dir="ltr" className="sd-type-caption-medium sd-tabular">
            <strong className="sd-pagination__current sd-type-caption-medium-emphasized">{currentPage}</strong>
            {" / "}
            {pageCount}
          </span>
          <span className="sd-visually-hidden">{statusLabel(currentPage, pageCount)}</span>
        </span>
        <Button
          variant="ghost"
          size="small"
          isIconOnly
          aria-label={nextName}
          data-layout="compact"
          className="sd-pagination__control"
          isDisabled={currentPage >= pageCount}
          onPress={() => onPageChange(currentPage + 1)}
        >
          <ChevronRight aria-hidden size="1em" />
        </Button>
      </nav>
    );
  }

  return (
    <nav
      ref={ref}
      aria-label={ariaLabel}
      className={className ? `sd-pagination ${className}` : "sd-pagination"}
      style={style}
    >
      <Button
        variant="outline"
        size="medium"
        className="sd-pagination__control"
        isDisabled={currentPage <= 1}
        onPress={() => onPageChange(currentPage - 1)}
      >
        {previousLabel}
      </Button>
      {visiblePages.map((item, index) =>
        item === "ellipsis" ? (
          <span
            key={`ellipsis-${index}`}
            aria-hidden="true"
            className="sd-pagination__ellipsis sd-type-label-medium"
          >
            …
          </span>
        ) : (
          /* A page cell is a Button: a headless primitive exists, so it is borrowed (AGENTS.md
             category A) rather than reimplemented on a raw `<button>`. `aria-current` survives: it is a typed prop on
             `AriaButtonOptions` and `useButton` forwards it explicitly (verified in
             `react-aria/dist/private/button/useButton.mjs`). Note it does NOT come through
             `filterDOMProps`, which admits only `dir/lang/hidden/inert/translate` from `global`. */
          <Button
            key={item}
            variant="outline"
            size="medium"
            className="sd-pagination__page"
            aria-label={pageLabel(item)}
            aria-current={item === currentPage ? "page" : undefined}
            data-current={item === currentPage || undefined}
            onPress={() => onPageChange(item)}
          >
            {item}
          </Button>
        )
      )}
      <Button
        variant="outline"
        size="medium"
        className="sd-pagination__control"
        isDisabled={currentPage >= pageCount}
        onPress={() => onPageChange(currentPage + 1)}
      >
        {nextLabel}
      </Button>
    </nav>
  );
}

/* Pagination composes Button for every cell, so this file lives with a CROSS-FILE cascade it does
   not control. Two rules follow from that, both learned by measurement rather than by reading:

   1. **Never declare a SHORTHAND that Button also declares.** `transition` was declared here and,
      being a shorthand, reset `transition-property` wholesale. This rule and `.sd-button` are both
      (0,1,0) so stylesheet order decided, and this one won — computed `transition-property` came
      out `background-color, border-color`, dropping the `transform` Button transitions for its
      pressed scale, so the inherited press SNAPPED. Declaring nothing inherits Button's list, which
      already covers both properties this component needs.
   2. **Qualify anything that must beat a Button variant rule.** `[data-variant="outline"]` is
      (0,2,0), so a bare `[data-current]` ties it and order decides again. Adding the attribute
      makes it (0,3,0) and it wins on specificity instead of on luck — the same guard
      `Carousel.css` uses for its arrow background. */

.sd-pagination {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--sd-pagination-gap);
}

.sd-pagination__control {
  flex: 0 0 auto;
}

/* A page cell IS a `Button` (`variant="outline"` `size="medium"`), so this rule declares only what
   Button does NOT. A declaration Button already makes would be dead here and look fine, which is
   the worst kind of dead: nothing tells you the Cmp tokens describe a surface they no longer
   control.

   What Button already owns, and therefore what is not here: `position` · `display` · `align-items` ·
   `justify-content` · `cursor` · `outline: none` (same declarations in `.sd-button`), `height`
   (`.sd-button[data-size="medium"]` is 0,2,0 and beats 0,1,0), `padding-inline`
   (`:not([data-icon-only])[data-size="medium"]`, 0,3,0), `background` and `color`
   (`[data-variant="outline"]`, 0,2,0), and `border`/`border-radius` (declared in `.sd-button`
   itself at equal specificity, so stylesheet order decides them).

   `min-width` STAYS: nothing in Button declares it, and it is what makes a single-digit cell square
   instead of hugging its glyph. It is the one look this component still owns at rest. */
.sd-pagination__page {
  min-width: var(--sd-pagination-page-size);
}

/* Interaction state-layer overlay (ADR-0009); border-color change stays on the page. */
/* The state LAYER, the hover/press wash and the focus ring all come from Button now — this file
   used to hand-roll all three beside a `<Button>` import (see Pagination.tsx). What is still this
   component's own is the border recolour: a border that exists at rest and only changes colour is
   a colour-layer role, not a `state` construct (naming.md § Interaction state domain). */
.sd-pagination__page[data-hovered] {
  border-color: var(--sd-pagination-page-border-hover);
}

.sd-pagination__page[data-variant="outline"][data-current] {
  background: var(--sd-pagination-page-background-current);
  color: var(--sd-pagination-page-foreground-current);
  border-color: var(--sd-pagination-page-border-current);
}

.sd-pagination__ellipsis {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: var(--sd-pagination-ellipsis-size);
  height: var(--sd-pagination-ellipsis-size);
  color: var(--sd-pagination-ellipsis-foreground);
}

/* compact — `‹ n / m ›`: the status between two icon-only ghost Buttons. The chevrons follow the
   row to its logical ends under RTL; mirror the glyph with them (the Carousel idiom; `scale`
   composes with Button's pressed transform). */
.sd-pagination__control[data-layout="compact"]:dir(rtl) {
  scale: -1 1;
}
.sd-pagination__status {
  color: var(--sd-pagination-status-foreground);
}
.sd-pagination__current {
  color: var(--sd-pagination-status-current-foreground);
}
